from functools import lru_cache

@lru_cache(maxsize=None)
def bell_number(n):
    """
    Returns the nth Bell number using the Bell triangle method.

    :param n: The index of the Bell number to compute.
    :return: The nth Bell number.
    """
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        triangle = [[0] * (n + 1) for _ in range(n + 1)]
        triangle[0][0] = 1
        for i in range(1, n + 1):
            triangle[i][0] = triangle[i - 1][i - 1]
            for j in range(1, i + 1):
                triangle[i][j] = triangle[i][j - 1] + triangle[i - 1][j - 1]
        return triangle[n][0]
